CREATE TABLE public.property_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, position integer NOT NULL DEFAULT 0);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.property_categories TO anon,authenticated; GRANT ALL ON public.property_categories TO service_role;
ALTER TABLE public.property_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Open CRM access" ON public.property_categories FOR ALL TO anon,authenticated USING (true) WITH CHECK (true);
CREATE TABLE public.employee_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, position integer NOT NULL DEFAULT 0);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.employee_categories TO anon,authenticated; GRANT ALL ON public.employee_categories TO service_role;
ALTER TABLE public.employee_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Open CRM access" ON public.employee_categories FOR ALL TO anon,authenticated USING (true) WITH CHECK (true);
CREATE TABLE public.teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.teams TO anon,authenticated; GRANT ALL ON public.teams TO service_role;
ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Open CRM access" ON public.teams FOR ALL TO anon,authenticated USING (true) WITH CHECK (true);
CREATE TABLE public.properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), address text NOT NULL, city text NOT NULL, price numeric NOT NULL DEFAULT 0 CHECK(price>=0), sqft numeric NOT NULL DEFAULT 0 CHECK(sqft>=0), beds integer NOT NULL DEFAULT 0 CHECK(beds>=0), baths integer NOT NULL DEFAULT 0 CHECK(baths>=0), status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Pending','Sold')), category_id uuid NOT NULL REFERENCES public.property_categories(id) ON DELETE RESTRICT);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.properties TO anon,authenticated; GRANT ALL ON public.properties TO service_role;
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Open CRM access" ON public.properties FOR ALL TO anon,authenticated USING (true) WITH CHECK (true);
CREATE TABLE public.employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', category_id uuid NOT NULL REFERENCES public.employee_categories(id) ON DELETE RESTRICT, team_id uuid REFERENCES public.teams(id) ON DELETE SET NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.employees TO anon,authenticated; GRANT ALL ON public.employees TO service_role;
ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Open CRM access" ON public.employees FOR ALL TO anon,authenticated USING (true) WITH CHECK (true);
CREATE INDEX employees_category_idx ON public.employees(category_id); CREATE INDEX employees_team_idx ON public.employees(team_id); CREATE INDEX properties_category_idx ON public.properties(category_id);
CREATE FUNCTION public.swap_designations(first_id uuid, second_id uuid) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p1 integer; p2 integer; BEGIN PERFORM id FROM employee_categories WHERE id IN(first_id,second_id) ORDER BY id FOR UPDATE; SELECT position INTO p1 FROM employee_categories WHERE id=first_id; SELECT position INTO p2 FROM employee_categories WHERE id=second_id; UPDATE employee_categories SET position=CASE WHEN id=first_id THEN p2 ELSE p1 END WHERE id IN(first_id,second_id); END $$;
GRANT EXECUTE ON FUNCTION public.swap_designations(uuid,uuid) TO anon,authenticated;
CREATE FUNCTION public.save_crm_team(team_name text, member_ids uuid[], existing_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF existing_id IS NULL THEN INSERT INTO teams(name) VALUES(team_name) RETURNING id INTO tid; ELSE tid:=existing_id; UPDATE teams SET name=team_name WHERE id=tid; END IF; UPDATE employees SET team_id=NULL WHERE team_id=tid AND NOT(id=ANY(member_ids)); UPDATE employees SET team_id=tid WHERE id=ANY(member_ids); RETURN tid; END $$;
GRANT EXECUTE ON FUNCTION public.save_crm_team(text,uuid[],uuid) TO anon,authenticated;
